/*
* Score every fixture set on the shared inputs against MPFR, and write a summary.
*
* ## Notes
*
* -   Run with `node scripts/accuracy.js` from the package directory, after `node scripts/inputs.js` and the fixture runners.
* -   A fixture set is any JSON file under `test/fixtures/` (outside `inputs/`) with a `meta.source`. Fixtures without `meta`, such as the existing Julia fixtures, are on other inputs and are skipped.
* -   Echo check: every set's `x` must match the shared input file's values bit for bit (NaN matches NaN, as JSON cannot carry a payload), and its `meta.inputs` must be the SHA-256 of the shared input file. The script exits with a nonzero code if any check fails.
* -   Scoring: `javascript::stdlib` is this package's `lib/`, evaluated here. Every point is classified against the MPFR reference before any ULP distance is taken: errors (a `null` value), NaN on both sides, the same infinity on both sides, non-finite mismatches, and signed-zero mismatches are counted separately. The remaining points are scored with `@stdlib/number/float64/base/ulp-difference`.
* -   The summary is written to `scripts/build/summary.json`, which stdlib's `.gitignore` keeps out of commits.
*/

/* eslint-disable n/no-sync, no-console, max-lines */

'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var relative = require( 'path' ).relative;
var sep = require( 'path' ).sep;
var createHash = require( 'crypto' ).createHash;
var execSync = require( 'child_process' ).execSync;
var mkdirSync = require( 'fs' ).mkdirSync;
var statSync = require( 'fs' ).statSync;
var exists = require( '@stdlib/fs/exists' ).sync;
var readFileSync = require( '@stdlib/fs/read-file' ).sync;
var readDirSync = require( '@stdlib/fs/read-dir' ).sync;
var writeFileSync = require( '@stdlib/fs/write-file' ).sync;
var extname = require( '@stdlib/utils/extname' );
var dirname = require( '@stdlib/utils/dirname' );
var objectKeys = require( '@stdlib/utils/keys' );
var trim = require( '@stdlib/string/base/trim' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var isInfinite = require( '@stdlib/math/base/assert/is-infinite' );
var isNegativeZero = require( '@stdlib/math/base/assert/is-negative-zero' );
var isPositiveZero = require( '@stdlib/math/base/assert/is-positive-zero' );
var ulpdiff = require( '@stdlib/number/float64/base/ulp-difference' );
var toWords = require( '@stdlib/number/float64/base/to-words' );
var sqrt = require( '@stdlib/math/base/special/sqrt' );
var max = require( '@stdlib/math/base/special/max' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var NINF = require( '@stdlib/constants/float64/ninf' );
var format = require( '@stdlib/string/format' );
var log1p = require( './../lib' );


// VARIABLES //

var PKG = resolve( __dirname, '..' );
var FIXTURES = resolve( PKG, 'test', 'fixtures' );
var INPUTS = resolve( FIXTURES, 'inputs' );
var OUT = resolve( __dirname, 'build', 'summary.json' );
var REFERENCE = 'mpfr';
var STDLIB = 'javascript::stdlib'; // eslint-disable-line no-script-url
var EDGE = 'edge_cases';

// Score fields which are summed when scores are combined:
var COUNTS = [ 'n', 'exact', 'ulp1', 'ulp2plus', 'nan', 'infinite', 'nonfinite_mismatch', 'signed_zero_mismatch', 'errors', 'reference_errors', 'sum', 'sumsq' ];


// FUNCTIONS //

/**
* Returns the SHA-256 digest of a buffer.
*
* @private
* @param {Buffer} buf - buffer
* @returns {string} hexadecimal digest
*/
function sha256( buf ) {
	return createHash( 'sha256' ).update( buf ).digest( 'hex' );
}

/**
* Decodes a JSON value from a shared input or fixture file.
*
* @private
* @param {(number|string|null)} v - JSON value
* @throws {Error} must be a number, `null`, or one of `"NaN"`, `"Infinity"`, and `"-Infinity"`
* @returns {(number|null)} double, or `null` for an error
*/
function decode( v ) {
	if ( v === null ) {
		return null;
	}
	if ( v === 'NaN' ) {
		return NaN;
	}
	if ( v === 'Infinity' ) {
		return PINF;
	}
	if ( v === '-Infinity' ) {
		return NINF;
	}
	if ( typeof v !== 'number' ) {
		throw new Error( format( 'unexpected value: `%s`.', String( v ) ) );
	}
	return v;
}

/**
* Tests whether two doubles have the same bits (any NaN matches any NaN).
*
* @private
* @param {number} a - first value
* @param {number} b - second value
* @returns {boolean} boolean indicating whether the values match
*/
function sameBits( a, b ) {
	var wa;
	var wb;
	if ( isnan( a ) || isnan( b ) ) {
		return isnan( a ) && isnan( b );
	}
	wa = toWords( a );
	wb = toWords( b );
	return ( wa[ 0 ] === wb[ 0 ] && wa[ 1 ] === wb[ 1 ] );
}

/**
* Tests whether a filename has a `.json` extension.
*
* @private
* @param {string} name - filename
* @returns {boolean} boolean indicating whether the filename has a `.json` extension
*/
function isJSON( name ) {
	return extname( name ) === '.json';
}

/**
* Recursively lists JSON files beneath a directory.
*
* @private
* @param {string} dir - directory
* @param {StringArray} out - output array
* @returns {StringArray} output array
*/
function listJSON( dir, out ) {
	var names;
	var p;
	var i;

	names = readDirSync( dir ).sort();
	for ( i = 0; i < names.length; i++ ) {
		p = resolve( dir, names[ i ] );
		if ( statSync( p ).isDirectory() ) {
			listJSON( p, out );
		} else if ( isJSON( p ) ) {
			out.push( p );
		}
	}
	return out;
}

/**
* Returns an empty set of scores.
*
* ## Notes
*
* -   `sum` and `sumsq` accumulate the ULP distances and their squares, from which `finalize` computes the mean and RMS distance. They are not written to the summary.
*
* @private
* @returns {Object} scores
*/
function emptyScores() {
	return {
		'n': 0,
		'max': 0,
		'mean': 0,
		'rms': 0,
		'exact': 0,
		'ulp1': 0,
		'ulp2plus': 0,
		'nan': 0,
		'infinite': 0,
		'nonfinite_mismatch': 0,
		'signed_zero_mismatch': 0,
		'errors': 0,
		'reference_errors': 0,
		'sum': 0,
		'sumsq': 0
	};
}

/**
* Scores one point against its reference.
*
* @private
* @param {Object} s - scores
* @param {(number|null)} v - value, or `null` for an error
* @param {(number|null)} r - reference value
*/
function scorePoint( s, v, r ) {
	var d;
	if ( r === null ) {
		s.reference_errors += 1;
		return;
	}
	if ( v === null ) {
		s.errors += 1;
		return;
	}
	if ( isnan( v ) || isnan( r ) ) {
		if ( isnan( v ) && isnan( r ) ) {
			s.nan += 1;
		} else {
			s.nonfinite_mismatch += 1;
		}
		return;
	}
	if ( isInfinite( v ) || isInfinite( r ) ) {
		if ( v === r ) {
			s.infinite += 1;
		} else {
			s.nonfinite_mismatch += 1;
		}
		return;
	}
	if (
		( isNegativeZero( v ) && isPositiveZero( r ) ) ||
		( isPositiveZero( v ) && isNegativeZero( r ) )
	) {
		s.signed_zero_mismatch += 1;
		return;
	}
	d = ulpdiff( v, r );
	s.n += 1;
	s.sum += d;
	s.sumsq += d * d;
	s.max = max( s.max, d );
	if ( d === 0 ) {
		s.exact += 1;
	} else if ( d === 1 ) {
		s.ulp1 += 1;
	} else {
		s.ulp2plus += 1;
	}
}

/**
* Adds one set of scores into another.
*
* @private
* @param {Object} acc - accumulated scores
* @param {Object} s - scores to add
*/
function addScores( acc, s ) {
	var i;
	for ( i = 0; i < COUNTS.length; i++ ) {
		acc[ COUNTS[ i ] ] += s[ COUNTS[ i ] ];
	}
	acc.max = max( acc.max, s.max );
}

/**
* Finalizes a set of scores, computing the mean and RMS ULP distance.
*
* @private
* @param {Object} s - scores
* @returns {Object} scores
*/
function finalize( s ) {
	var keys;
	var out;
	var i;

	keys = objectKeys( s );
	out = {};
	for ( i = 0; i < keys.length; i++ ) {
		if ( keys[ i ] !== 'sum' && keys[ i ] !== 'sumsq' ) {
			out[ keys[ i ] ] = s[ keys[ i ] ];
		}
	}
	out.mean = ( s.n > 0 ) ? s.sum / s.n : null;
	out.rms = ( s.n > 0 ) ? sqrt( s.sumsq / s.n ) : null;
	if ( s.n === 0 ) {
		out.max = null;
	}
	return out;
}

/**
* Runs a git command in the package directory.
*
* @private
* @param {string} args - command arguments
* @returns {(string|null)} trimmed output, or `null` on failure
*/
function git( args ) {
	try {
		return trim( execSync( 'git '+args, {
			'cwd': PKG,
			'encoding': 'utf8',
			'stdio': [ 'ignore', 'pipe', 'ignore' ]
		}) );
	} catch ( err ) { // eslint-disable-line no-unused-vars
		return null;
	}
}

/**
* Pads a string on the left.
*
* @private
* @param {*} v - value
* @param {NonNegativeInteger} n - width
* @returns {string} padded string
*/
function lpad( v, n ) {
	var s = ( v === null ) ? '-' : String( v );
	while ( s.length < n ) {
		s = ' ' + s;
	}
	return s;
}

/**
* Reads the shared inputs.
*
* @private
* @param {StringArray} failures - list of failed checks, appended to
* @returns {Object} inputs, by regime
*/
function readInputs( failures ) {
	var inputs;
	var files;
	var json;
	var data;
	var x;
	var i;
	var j;

	inputs = {};
	files = readDirSync( INPUTS ).filter( isJSON ).sort();
	for ( i = 0; i < files.length; i++ ) {
		json = readFileSync( resolve( INPUTS, files[ i ] ) );
		data = JSON.parse( json.toString() );
		x = [];
		for ( j = 0; j < data.x.length; j++ ) {
			x.push( decode( data.x[ j ] ) );
		}
		if ( x.length !== data.meta.n ) {
			failures.push( format( 'inputs/%s: %d values, but `meta.n` is %d.', files[ i ], x.length, data.meta.n ) );
		}
		inputs[ data.regime ] = {
			'x': x,
			'sha256': sha256( json ),
			'meta': data.meta
		};
	}
	return inputs;
}

/**
* Discovers the fixture sets on the shared inputs.
*
* @private
* @returns {Object} sets, by source, plus the fixtures skipped and the bytes per source
*/
function discoverSets() {
	var sources;
	var skipped;
	var bytes;
	var files;
	var data;
	var src;
	var f;
	var i;

	sources = {};
	skipped = [];
	bytes = {};
	files = listJSON( FIXTURES, [] );
	for ( i = 0; i < files.length; i++ ) {
		f = files[ i ];
		if ( f.indexOf( INPUTS+sep ) === 0 ) {
			continue;
		}
		data = JSON.parse( readFileSync( f ).toString() );
		if ( !data.meta || !data.meta.source ) {
			skipped.push( relative( PKG, f ) );
			continue;
		}
		src = data.meta.source;
		if ( !sources[ src ] ) {
			sources[ src ] = {
				'dir': relative( PKG, dirname( f ) ),
				'sets': {}
			};
			bytes[ src ] = 0;
		}
		bytes[ src ] += statSync( f ).size;
		sources[ src ].sets[ data.meta.regime ] = data;
	}
	return {
		'sources': sources,
		'skipped': skipped,
		'bytes': bytes
	};
}

/**
* Checks that every set echoes the shared inputs bit for bit, and names the input file it read.
*
* @private
* @param {Object} sources - sets, by source
* @param {Object} inputs - shared inputs, by regime
* @param {StringArray} failures - list of failed checks, appended to
* @returns {Object} echo results, by source and regime
*/
function echoCheck( sources, inputs, failures ) {
	var regimes;
	var names;
	var echo;
	var name;
	var src;
	var set;
	var ok;
	var x;
	var i;
	var j;
	var k;
	var m;

	regimes = objectKeys( inputs );
	names = objectKeys( sources );
	echo = {};
	for ( m = 0; m < names.length; m++ ) {
		src = names[ m ];
		echo[ src ] = {};
		for ( i = 0; i < regimes.length; i++ ) {
			name = regimes[ i ];
			set = sources[ src ].sets[ name ];
			if ( !set ) {
				failures.push( format( '%s: missing regime `%s`.', src, name ) );
				continue;
			}
			x = inputs[ name ].x;
			k = 0;
			if ( set.x.length === x.length ) {
				for ( j = 0; j < x.length; j++ ) {
					if ( !sameBits( decode( set.x[ j ] ), x[ j ] ) ) {
						k += 1;
					}
				}
			} else {
				k = -1;
			}
			ok = ( set.meta.inputs === inputs[ name ].sha256 );
			echo[ src ][ name ] = {
				'n': set.x.length,
				'mismatches': k,
				'inputs_hash_matches': ok
			};
			if ( k !== 0 ) {
				failures.push( format( '%s/%s: echoed inputs differ (%d).', src, name, k ) );
			}
			if ( !ok ) {
				failures.push( format( '%s/%s: `meta.inputs` does not match the shared input file.', src, name ) );
			}
		}
	}
	return echo;
}

/**
* Returns the summary's description of a source.
*
* @private
* @param {string} src - source name
* @param {Object} sources - sets, by source
* @param {string} first - name of a regime whose set carries the source's metadata
* @param {(string|null)} commit - stdlib commit
* @returns {Object} description
*/
function describe( src, sources, first, commit ) {
	var meta;
	if ( src === STDLIB ) {
		return {
			'source': STDLIB,
			'function': '@stdlib/math/base/special/log1p',
			'implementation': "stdlib's own JavaScript (lib/main.js), evaluated by the scorer",
			'versions': {
				'node': process.version,
				'stdlib': commit
			},
			'platform': {
				'os': process.platform,
				'arch': process.arch,
				'compiler': null
			}
		};
	}
	meta = sources[ src ].sets[ first ].meta;
	return {
		'source': meta.source,
		'function': meta.function,
		'implementation': meta.implementation,
		'versions': meta.versions,
		'platform': meta.platform,
		'generated': meta.generated,
		'dir': sources[ src ].dir
	};
}

/**
* Scores one source against MPFR, by regime and in total.
*
* @private
* @param {string} src - source name
* @param {Object} sources - sets, by source
* @param {Object} inputs - shared inputs, by regime
* @returns {Object} scores
*/
function scoreSource( src, sources, inputs ) {
	var regimes;
	var name;
	var tot;
	var ref;
	var set;
	var out;
	var sc;
	var x;
	var v;
	var j;
	var k;

	regimes = objectKeys( inputs );
	out = {};
	tot = emptyScores();
	for ( j = 0; j < regimes.length; j++ ) {
		name = regimes[ j ];
		ref = sources[ REFERENCE ].sets[ name ];
		set = ( src === STDLIB ) ? null : sources[ src ].sets[ name ];
		sc = emptyScores();
		x = inputs[ name ].x;
		for ( k = 0; k < x.length; k++ ) {
			v = ( set ) ? decode( set.expected[ k ] ) : log1p( x[ k ] );
			scorePoint( sc, v, decode( ref.expected[ k ] ) );
		}
		if ( name !== EDGE ) {
			addScores( tot, sc );
		}
		out[ name ] = finalize( sc );
	}
	return {
		'regimes': out,
		'total': finalize( tot )
	};
}

/**
* Prints the summary as a table, followed by the echo check's result.
*
* @private
* @param {Object} summary - summary
*/
function printTable( summary ) {
	var regimes;
	var keys;
	var row;
	var sc;
	var i;
	var j;

	keys = objectKeys( summary.sources );
	console.log( 'Scored against %s; summary written to %s', REFERENCE, relative( PKG, OUT ) );
	console.log( '' );
	console.log( '%s %s %s %s %s %s %s %s %s', lpad( 'source', 20 ), lpad( 'regime', 16 ), lpad( 'n', 5 ), lpad( 'max', 4 ), lpad( 'mean', 8 ), lpad( 'exact', 6 ), lpad( '1ulp', 5 ), lpad( '>=2', 4 ), lpad( 'other', 22 ) );
	for ( i = 0; i < keys.length; i++ ) {
		row = summary.sources[ keys[ i ] ];
		regimes = objectKeys( row.regimes );
		for ( j = 0; j < regimes.length; j++ ) {
			sc = row.regimes[ regimes[ j ] ];
			console.log( '%s %s %s %s %s %s %s %s %s', lpad( keys[ i ], 20 ), lpad( regimes[ j ], 16 ), lpad( sc.n, 5 ), lpad( sc.max, 4 ), lpad( ( sc.mean === null ) ? null : sc.mean.toFixed( 4 ), 8 ), lpad( sc.exact, 6 ), lpad( sc.ulp1, 5 ), lpad( sc.ulp2plus, 4 ), lpad( format( 'nan %d inf %d nf! %d err %d', sc.nan, sc.infinite, sc.nonfinite_mismatch+sc.signed_zero_mismatch, sc.errors ), 22 ) );
		}
		sc = row.total;
		console.log( '%s %s %s %s %s %s %s %s', lpad( keys[ i ], 20 ), lpad( 'TOTAL', 16 ), lpad( sc.n, 5 ), lpad( sc.max, 4 ), lpad( sc.mean.toFixed( 4 ), 8 ), lpad( sc.exact, 6 ), lpad( sc.ulp1, 5 ), lpad( sc.ulp2plus, 4 ) );
	}
	console.log( '' );
	console.log( 'Echo check: %s', ( summary.failures.length === 0 ) ? 'every set matches the shared inputs bit for bit.' : 'FAILED' );
	for ( i = 0; i < summary.failures.length; i++ ) {
		console.log( '  - %s', summary.failures[ i ] );
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
* @throws {Error} must have MPFR reference fixtures
*/
function main() {
	var failures;
	var summary;
	var regimes;
	var inputs;
	var commit;
	var found;
	var keys;
	var name;
	var row;
	var i;

	failures = [];
	inputs = readInputs( failures );
	regimes = objectKeys( inputs );
	found = discoverSets();
	commit = git( 'rev-parse HEAD' );
	if ( !found.sources[ REFERENCE ] ) {
		throw new Error( 'no MPFR reference fixtures found.' );
	}
	summary = {
		'meta': {
			'package': '@stdlib/math/base/special/log1p',
			'generated': new Date().toISOString().replace( /\.\d+Z$/, 'Z' ),
			'scorer': 'scripts/accuracy.js',
			'reference': REFERENCE,
			'stdlib': {
				'commit': commit,
				'uncommitted_changes_in_package': ( git( 'status --porcelain -- .' ) || '' ).length > 0
			},
			'node': process.version,
			'metric': 'ULP distance from MPFR (`@stdlib/number/float64/base/ulp-difference`), on finite, same-signed-zero pairs; non-finite, NaN, signed-zero and error cases counted separately',
			'totals_exclude': [ EDGE ]
		},
		'inputs': {},
		'echo': echoCheck( found.sources, inputs, failures ),
		'sources': {},
		'fixture_bytes': found.bytes,
		'skipped_fixtures': found.skipped,
		'failures': failures
	};
	for ( i = 0; i < regimes.length; i++ ) {
		name = regimes[ i ];
		summary.inputs[ name ] = {
			'n': inputs[ name ].x.length,
			'distribution': inputs[ name ].meta.distribution,
			'domain': inputs[ name ].meta.domain,
			'prng': inputs[ name ].meta.prng,
			'seed': inputs[ name ].meta.seed,
			'sha256': inputs[ name ].sha256
		};
	}
	keys = [ STDLIB ].concat( objectKeys( found.sources ).sort() );
	for ( i = 0; i < keys.length; i++ ) {
		row = scoreSource( keys[ i ], found.sources, inputs );
		row.meta = describe( keys[ i ], found.sources, regimes[ 0 ], commit );
		summary.sources[ keys[ i ] ] = {
			'meta': row.meta,
			'regimes': row.regimes,
			'total': row.total
		};
	}
	if ( !exists( dirname( OUT ) ) ) {
		mkdirSync( dirname( OUT ) );
	}
	writeFileSync( OUT, JSON.stringify( summary, null, '  ' )+'\n' );
	printTable( summary );
	if ( failures.length > 0 ) {
		process.exitCode = 1;
	}
}

main();
